    INSERT INTO exams (title, description, code, is_active, start_date, end_date, total_points, grade, group_name, block, teacher_id, created_at, updated_at) VALUES ('Examen Final IV (Necaxa) (Grupo E)', 'Responde las siguientes preguntas. Para los algoritmos puedes usar lápiz y papel. Par las conversiones de números binarios puedes usar lápiz, papel y calculadora.', 'LINGÜINI', true, '2026-11-20T17:30:00', '2026-11-21T06:40:00', 10, '4to', 'E', 3, v_teacher_id, NOW(), NOW()) RETURNING id INTO v_exam_id;
    INSERT INTO questions (prompt, type, points, question_order, correct_answer, question_data, image_url, exam_id) VALUES ('El el protocolo de red que otorga una IP a cada dispositivo dentro de una red:', 'MULTIPLE_CHOICE', 0.56, 1, '["DHCP"]', '{"options":["PSP","DM","DHCP","GameBoy"],"allowMultiple":false}', NULL, v_exam_id);
    INSERT INTO questions (prompt, type, points, question_order, correct_answer, question_data, image_url, exam_id) VALUES ('Es un algoritmo que busca encontrar el árbol de expansión mínima, es decir, un árbol conexo con los costos mínimos posibles en sus arcos.', 'MULTIPLE_CHOICE', 0.56, 2, '["Kruskal"]', '{"options":["Marshal","Kruskal","Mendel","Krusty Krab"],"allowMultiple":false}', NULL, v_exam_id);
    INSERT INTO questions (prompt, type, points, question_order, correct_answer, question_data, image_url, exam_id) VALUES ('¿Qué es un grafo?', 'MULTIPLE_CHOICE', 0.56, 3, '["Una serie de nodos  que pueden estar conectados entre sí con arcos."]', '{"options":["Una serie de nodos  que pueden estar conectados entre sí con arcos.","Una forma de graficar ciudades, y nada más.","Un gráfico de barras","Un histograma"],"allowMultiple":false}', NULL, v_exam_id);
    INSERT INTO questions (prompt, type, points, question_order, correct_answer, question_data, image_url, exam_id) VALUES ('¿Es posible que existan grafos sin arcos (líneas)?', 'MULTIPLE_CHOICE', 0.56, 4, '["Sí, es un grafo inconexo"]', '{"options":["Sí, pero se llaman árboles","Sí, es un grafo inconexo","No, deja de ser un grafo si no tiene líneas","No, eso son direcciones IP"],"allowMultiple":false}', NULL, v_exam_id);
    INSERT INTO questions (prompt, type, points, question_order, correct_answer, question_data, image_url, exam_id) VALUES ('Un árbol es una colección de nodos que están interconectados y pueden tener ciclos enter sí, para formar caminos más completos.', 'TRUE_FALSE', 0.56, 5, 'false', '{}', NULL, v_exam_id);
    INSERT INTO questions (prompt, type, points, question_order, correct_answer, question_data, image_url, exam_id) VALUES ('Todo árbol es un grafo, pero no todo grafo es un árbol.', 'TRUE_FALSE', 0.56, 6, 'true', '{}', NULL, v_exam_id);
    INSERT INTO questions (prompt, type, points, question_order, correct_answer, question_data, image_url, exam_id) VALUES ('Es una de las reglas para que un grafo sea un árbol.', 'MULTIPLE_CHOICE', 0.56, 7, '["No debe tener ciclos"]', '{"options":["Su nodo inicial debe estar hasta arriba","No debe tener ciclos","Tiene que tener al menor siete nodos","Debe tener ramas y tronco"],"allowMultiple":false}', NULL, v_exam_id);
    INSERT INTO questions (prompt, type, points, question_order, correct_answer, question_data, image_url, exam_id) VALUES ('Es un algoritmo que busca encontrar el camino más corto para llegar de un punto de origen a un destino en un grafo.', 'MULTIPLE_CHOICE', 0.56, 8, '["Djikstra"]', '{"options":["Ampliación de espectro","Random forest","Umbra","Djikstra"],"allowMultiple":false}', NULL, v_exam_id);
    INSERT INTO questions (prompt, type, points, question_order, correct_answer, question_data, image_url, exam_id) VALUES ('En el siguiente grafo, aplica Kruskal para encontrar su árbol de expansión mínima', 'MULTIPLE_CHOICE', 0.56, 9, '["A -- D (5);  C -- B (3); B -- D (3). Peso total: 11"]', '{"options":["A -- D (5);  C -- B (3); B -- D (3). Peso total: 16","A -- D (5);  C -- B (3); B -- D (3). Peso total: 11","A -- C (7);  C -- B (3); B -- D (3). Peso total: 8","A -- D (5);  D -- B (3); C -- D (5). Peso total: 11"],"allowMultiple":false}', 'data:image/jpeg;base64,', v_exam_id);
    INSERT INTO questions (prompt, type, points, question_order, correct_answer, question_data, image_url, exam_id) VALUES ('¿Cuáles arcos sería válido quitar para que el siguiente grafo sea un árbol?  (selecciona las que apliquen)', 'MULTIPLE_CHOICE', 0.56, 10, '["A -- C (7); B -- D (3); y C -- D (5)","C-- B  (3); y  C -- D (5)"]', '{"options":["A -- D (5); A--C (7); y B -- D (3)","A -- C (7); C -- B (3); y C -- D (5)","A -- C (7); B -- D (3); y C -- D (5)","C-- B  (3); y  C -- D (5)"],"allowMultiple":true}', 'data:image/jpeg;base64,', v_exam_id);
    INSERT INTO questions (prompt, type, points, question_order, correct_answer, question_data, image_url, exam_id) VALUES ('Convierte el siguiente número binario a decimal: 10110', 'MULTIPLE_CHOICE', 0.55, 11, '["22"]', '{"options":["11","22","16","255"],"allowMultiple":false}', NULL, v_exam_id);
    INSERT INTO questions (prompt, type, points, question_order, correct_answer, question_data, image_url, exam_id) VALUES ('¿Por qué la base numérica de los números binarios es 2?', 'MULTIPLE_CHOICE', 0.55, 12, '["Porque emplean dos dígitos: 0 y 1"]', '{"options":["Porque es más barato financieramente","Porque emplean dos dígitos: 0 y 1","Para que sea más fácil de aprender","Porque no sabían contar"],"allowMultiple":false}', NULL, v_exam_id);
    INSERT INTO questions (prompt, type, points, question_order, correct_answer, question_data, image_url, exam_id) VALUES ('¿Cuál es la base numérica del sistema de numeración DECIMAL?', 'MULTIPLE_CHOICE', 0.55, 13, '["10"]', '{"options":["8","16","10","2"],"allowMultiple":false}', NULL, v_exam_id);
    INSERT INTO questions (prompt, type, points, question_order, correct_answer, question_data, image_url, exam_id) VALUES ('¿Cuál es la base numérica del sistema de numeración HEXADECIMAL?', 'MULTIPLE_CHOICE', 0.55, 14, '["16"]', '{"options":["32 bits","8","16","2"],"allowMultiple":false}', NULL, v_exam_id);
    INSERT INTO questions (prompt, type, points, question_order, correct_answer, question_data, image_url, exam_id) VALUES ('¿Para qué sirve un grafo?', 'MULTIPLE_CHOICE', 0.55, 15, '["Para representar todo tipo de problemas matemáticos, estadísticos, sociales, etc."]', '{"options":["Para representar todo tipo de problemas matemáticos, estadísticos, sociales, etc.","Para representar la naturaleza y la forma en que las raíces de los árboles crecen.","Para nada, los grafos  son inútiles.","Para complicar las matemáticas, haciendo que además de números, veas letras y líneas."],"allowMultiple":false}', NULL, v_exam_id);
    INSERT INTO questions (prompt, type, points, question_order, correct_answer, question_data, image_url, exam_id) VALUES ('Es un algoritmo de búsqueda que busca elementos en un grafo, empezando de la raíz y visitando TODOS los VECINOS de cada nodo.', 'MULTIPLE_CHOICE', 0.55, 16, '["Búsqueda en anchura"]', '{"options":["Krusty Krab","Búsqueda en anchura","Búsqueda en profundidad","Kruskal"],"allowMultiple":false}', NULL, v_exam_id);
    INSERT INTO questions (prompt, type, points, question_order, correct_answer, question_data, image_url, exam_id) VALUES ('Es un  algoritmo que explora todos los nodos en un solo camino hasta que no quedan más nodos sin visitar, luego vuelve sobre sus pasos (Backtracking) para seguir revisando los caminos no explorados.', 'MULTIPLE_CHOICE', 0.55, 17, '["Búsqueda en profundidad"]', '{"options":["Búsqueda en anchura","Búsqueda en profundidad","Algoritmo de  A-Star","Búsqueda binaria"],"allowMultiple":false}', NULL, v_exam_id);
    INSERT INTO questions (prompt, type, points, question_order, correct_answer, question_data, image_url, exam_id) VALUES ('En el siguiente grafo, usa Djikstra para encontrar el camino más rápido para llegar desde A hasta B. Y su peso.', 'MULTIPLE_CHOICE', 0.55, 18, '["A → C → B. Peso: 6"]', '{"options":["A → E → B: 12","A → C → B. Peso: 7","A → C → B. Peso: 6","A → E → B: 15"],"allowMultiple":false}', 'data:image/jpeg;base64,', v_exam_id);
