-- Script de importacion para el Examen Final IV
DO $$
DECLARE
    v_teacher_id bigint;
    v_exam_id bigint;
BEGIN
    SELECT id INTO v_teacher_id FROM users WHERE role = 'ROLE_TEACHER' ORDER BY id ASC LIMIT 1;
    IF v_teacher_id IS NULL THEN
        RAISE EXCEPTION 'No se encontro ningun usuario profesor (ROLE_TEACHER) para asignar el examen.';
    END IF;

    DELETE FROM questions WHERE exam_id IN (SELECT id FROM exams WHERE code = 'LINGÜINI');
    DELETE FROM exams WHERE code = 'LINGÜINI';



    RAISE NOTICE 'Examen importado exitosamente con ID: %', v_exam_id;
END $$;